describe('Geotic Breath mob skill',function()
 it('enforces its gates, requests Earth breath, adjusts conal damage, and damages only after processing',function()
  local breath=require('scripts/actions/mobskills/geotic_breath');local move,adjust,process=xi.mobskills.mobBreathMove,utils.conalDamageAdjustment,xi.mobskills.processDamage;local params,damage=nil,nil;local invincible,infront,animation=false,true,0;local mob={hasStatusEffect=function()return invincible end,getAnimationSub=function()return animation end};local target={isInfront=function(_,other,angle)return other==mob and angle==128 and infront end,takeDamage=function(_,...)damage={...}end};assert(breath.onMobSkillCheck(target,mob,{})==0);invincible=true;assert(breath.onMobSkillCheck(target,mob,{})==1);invincible=false;infront=false;assert(breath.onMobSkillCheck(target,mob,{})==1);infront=true;animation=1;assert(breath.onMobSkillCheck(target,mob,{})==1);animation=0
  xi.mobskills.mobBreathMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.BREATH,damageType=xi.damageType.EARTH}end;utils.conalDamageAdjustment=function(_,_,_,value,amount)assert(value==123 and amount==.2);return 99 end;xi.mobskills.processDamage=function()return false end;assert(breath.onMobWeaponSkill(mob,target,{},{})==99);assert(params.percentMultipier==.15 and params.damageCap==1150 and params.bonusDamage==0 and params.mAccuracyBonus[1]==0 and params.mAccuracyBonus[2]==0 and params.mAccuracyBonus[3]==0 and params.resistStat==xi.mod.INT and params.element==xi.element.EARTH and params.attackType==xi.attackType.BREATH and params.damageType==xi.damageType.EARTH and params.shadowBehavior==xi.mobskills.shadowBehavior.IGNORE_SHADOWS and damage==nil);xi.mobskills.processDamage=function()return true end;breath.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobBreathMove,utils.conalDamageAdjustment,xi.mobskills.processDamage=move,adjust,process;assert(damage[1]==99 and damage[2]==mob and damage[3]==xi.attackType.BREATH and damage[4]==xi.damageType.EARTH)
 end)
end)
